typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

TreeNode* newNode(int v) {
    TreeNode* n = (TreeNode*)malloc(sizeof(TreeNode));
    n->val = v; n->left = NULL; n->right = NULL;
    return n;
}

static void skip_ws(const char **p) {
    while (**p && (isspace((unsigned char)**p) || **p == ',')) (*p)++;
}

static int parse_value(const char **p, bool *is_null) {
    skip_ws(p);
    if (strncmp(*p, "null", 4) == 0) {
        *is_null = true;
        *p += 4;
        return 0;
    }
    *is_null = false;
    int sign = 1;
    if (**p == '-') { sign = -1; (*p)++; }
    int v = 0;
    while (isdigit((unsigned char)**p)) {
        v = v * 10 + (**p - '0');
        (*p)++;
    }
    return sign * v;
}

/* Build without losing root pointer. */
TreeNode* build_tree(const char *s) {
    const char *p = strchr(s + 1, '[');
    if (!p) return NULL;
    p++;
    int vals[2000], present[2000], n = 0;
    while (*p && *p != ']' && n < 2000) {
        bool is_null = false;
        vals[n] = parse_value(&p, &is_null);
        present[n] = !is_null;
        n++;
        skip_ws(&p);
    }
    if (n == 0 || !present[0]) return NULL;

    TreeNode **nodes = (TreeNode**)calloc(n, sizeof(TreeNode*));
    for (int i = 0; i < n; ++i)
        if (present[i]) nodes[i] = newNode(vals[i]);

    TreeNode *root = nodes[0];
    TreeNode **queue = (TreeNode**)malloc(n * sizeof(TreeNode*));
    int head = 0, tail = 0, i = 1;
    queue[tail++] = root;
    while (head < tail && i < n) {
        TreeNode *cur = queue[head++];
        cur->left = nodes[i];
        if (nodes[i]) queue[tail++] = nodes[i];
        i++;
        if (i < n) {
            cur->right = nodes[i];
            if (nodes[i]) queue[tail++] = nodes[i];
            i++;
        }
    }
    free(queue);
    free(nodes);
    return root;
}

void zigzag_and_print(TreeNode *root) {
    if (!root) { printf("[]\n"); return; }

    TreeNode **queue = (TreeNode**)malloc(2000 * sizeof(TreeNode*));
    TreeNode **level = (TreeNode**)malloc(2000 * sizeof(TreeNode*));
    int head = 0, tail = 0;
    queue[tail++] = root;
    bool left_to_right = true;
    bool first_level = true;

    printf("[");
    while (head < tail) {
        int level_count = tail - head;
        for (int i = 0; i < level_count; ++i)
            level[i] = queue[head + i];

        if (!first_level) printf(",");
        printf("[");
        for (int j = 0; j < level_count; ++j) {
            int idx = left_to_right ? j : (level_count - 1 - j);
            if (j) printf(",");
            printf("%d", level[idx]->val);
        }
        printf("]");

        int new_tail = 0;
        /* Reuse queue from current head onward by rebuilding next level. */
        for (int i = 0; i < level_count; ++i) {
            TreeNode *node = level[i];
            if (node->left) queue[new_tail++] = node->left;
            if (node->right) queue[new_tail++] = node->right;
        }
        head = 0;
        tail = new_tail;
        left_to_right = !left_to_right;
        first_level = false;
    }
    printf("]\n");
    free(queue);
    free(level);
}

